 * W = sum w_i*(d_i+1) mod 256 with w_i = 2i+1?
 * A permutation escapes iff sum (w_i - w_{s(i)})*d_{s(i)} == 0, i.e.
 * sum_i c_i * d_{s(i)} = 0 where c_i = w_i - w_{s(i)}.
 * For rotations s(i) = (i+k)%8: escape iff sum_i (w_i - w_{i-k})*d_{i-k} = 0.
 * That is a linear functional of the data vector → data-dependent.
 * The counting data d_j = j hits the zero of the functional for some k.
 * A second independent aggregate with different weights kills these
 * structured escapes: collision probability 1/256^2 per event.
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <stdbool.h>

static uint8_t w1(unsigned i){ return (uint8_t)(2*i+1); }   /* 1,3,..,15 */
static uint8_t w2(unsigned i){ return (uint8_t)(2*i+1) ^ 0x5A; } /* must stay odd & distinct */
/* check w2 distinctness: 1^0x5A=0x5B, 3^5A=59,... verify at runtime */

static uint16_t agg(const uint8_t*d,unsigned n,int which){
    unsigned s=0;
